components/gordonbyte/common/blog/blog:
{{assignVar "posts_count" theme_settings.homepage_blog_posts_count}}

{{#if theme_settings.homepage_blog_posts_count '!=' 0}}

<div class="recentBlogs">

    <h2 class="page-heading">{{ theme_settings.gb-home-blogs-header }}</h2>

    <div class="recentBlog-holder">
    {{#each blog.recent_posts}}
    <div class="recentBlog{{#if theme_settings.gb-animation-enable }} gb-animate-me animate__animated{{/if}}" {{#if theme_settings.gb-animation-enable }}data-animation="fadeIn"{{/if}}>
      <a href="{{url}}">
        <div class="recentBlog-img{{#unless thumbnail }} no-img-size{{/unless}}">
          {{#if thumbnail }}
            <img src="{{getImage thumbnail }}"
                  data-sizes="auto"
                  alt="{{title}}"
                  {{#unless lazyload '==' 'disabled'}}
                      {{#if lazyload '==' 'lazyload+lqip'}}
                      {{!-- If we want a LQIP, include it as the default srcset (will be overwritten by lazysizes) --}}
                      srcset="{{getImageSrcset thumbnail}}"
                      {{else}}
                        {{!-- If we don't want a LQIP, use a 1px transparent gif for the stand-in image
                              This requires no additional network request, so it's fast --}}
                      srcset="data:image/gif;base64,R0lGODlhAQABAIAAAP///wAAACH5BAEAAAAALAAAAAABAAEAAAICRAEAOw=="
                      {{/if}}
                  {{/unless}}

                  {{#unless lazyload '==' 'disabled'}}data-{{/unless}}srcset="{{getImageSrcset thumbnail use_default_sizes=true }}"

                  class="{{#unless lazyload '==' 'disabled'}}lazyload{{/unless}}"
                  {{#if lazyload '==' 'lazyload'}}loading="lazy"{{/if}}
                  >

            {{else}}
              {{> components/gordonbyte/common/no-img }}
            {{/if}}
        </div><!--.recentBlog-img end-->

        <div class="recentBlog-info">
          <h3>{{title}}</h3>
          <div class="blogInfo">
            {{summary}}
          </div><!--.blogInfo ends-->
		  <div class="button">{{uppercase (lang 'blog.read_more')}}</div>
        </div><!--.recentBlog-info end-->
      </a>
    </div><!--.recentBlog ends-->
    {{/each}}

    </div>
	<div class="allResources">
		<a href="/resources/" class="button">SEE ALL RESOURCES</a>
	</div>
</div><!--.recentBlogs ends-->

{{/if}}
